local InvestMainDialog = Class("InvestMainDialog")
local RewardCellPath = "Game.UI.OverseaInvest.InvestMainDialogCell"
local RewardCount = 3
---@type PlayerComponent
local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)

function InvestMainDialog:__init()
    self._showTimeLimitedMainDialogWhenClose = false
end

function InvestMainDialog:Awake()
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
    self:AddUIClick()
    local allVo = CfUtils.GetCf(AutoIds.IdSetting3087, "FirstPayRewardVo", true)
    self.vo = allVo[1]
    self:InitEnv()
    -- self:SetStaticInfo()
    KTool.SetActive(self.BtnRoleNameNode, false)
    self._showTimeLimitedMainDialogWhenClose = false
end

function InvestMainDialog:SetStaticInfo()
    self:SetPriceInfo()
end

function InvestMainDialog:SetPriceInfo()
    if self:IsGoodExchange() then
        local path = GoodsConfMgr:GetInstance():GetPhotoPathById(self.data.currency)
        CfUtils.FillImage(self.originImgIcon ,path)
        local prices = self.data.prices
        if isNotNull(prices) then
            local original = checkNumber(prices.original)
            if original == 0  then
                KTool.SetActive(self.TxtOriginalCost , false)
                return     
            end
            CfUtils.FillText(self.TxtOriginalCost, original)
       end
    else 
        CfUtils.FillText(self.TxtOriginalCost,CfUtils.GetDisplayPrice(self.vo.originalPrice))
    end
end

function InvestMainDialog:InitEnv()
    self.rewardEnv = {}
    for i = 1, RewardCount do
        local node = self["Cell"..i]
        if node then
            local env = CfUtils.GetLuaScr(node,RewardCellPath)
            env:SetCallBackAndIndex(i,Bind(self,self.OnGetRewardClick))
            if env then
               self.rewardEnv[i] = env
            end
        end
    end
end

function InvestMainDialog:OnGetRewardClick(i)
    GameUtils.Request(Interfaces.OverseaFirstPayDrawReward,{day = i},function(request,response)
        if checkInt(response.errCode) == 0 then
            local responseData = response.data
            self:RefreshShow()
            if #responseData.rewards > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end
        end
    end)
end

function InvestMainDialog:AddUIClick()
    SetButtonAction(self.BtnClose.gameObject, function()
        self:PanelClose()
    end)
    KTool.GetOrAddComponent(self.ImgBg.gameObject, typeof(CS.Engine.UI.UIEventProxy)).onPointerClick = function()
        self:PanelClose()
    end

    SetButtonAction(self.BtnHaveBuy.gameObject,function()
        --GameUtils.Toast(localize(""))
    end)

    SetButtonAction(self.BtnBuy.gameObject,function()
        self:OnBuy()
    end)

end

function InvestMainDialog:PanelClose(pRewards)
    local tempData = clone(self.data)
    CfUtils.StartCoroutineWithBlocker(function()
        ---@type LimitedTimeSaleMgr
        local LimitedTimeSaleMgr = import("Game.UI.LimitedTimeSale.LimitedTimeSaleMgr"):GetInstance()
        LimitedTimeSaleMgr:SetNeedOpenTimeLimitedDialog(self._showTimeLimitedMainDialogWhenClose)

        cs_coroutine.yield_return(UIModule.BackDialog())
        if not isNull(pRewards) and #pRewards > 0 then
            GoodsUtils.DrawRewards(pRewards, true)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = pRewards } ,cb = function()
                if self:IsNeedPlay(tempData) then
                    Events.Broadcast(Constants.EventNames.START_SHOW_BOOM_MOVE,Constants.UIHomeViewBtnType.BtnFirstFlush)
                end
            end })
        else
            if self:IsNeedPlay(tempData) then
                Events.Broadcast(Constants.EventNames.START_SHOW_BOOM_MOVE,Constants.UIHomeViewBtnType.BtnFirstFlush)
            end
        end
    end)
end

function InvestMainDialog:IsNeedPlay(tempData)
    local isAllGet = isSet(tempData,"receiveId") and table.count(tempData.receiveId) >= 3
    return (not isAllGet) and (not self._showTimeLimitedMainDialogWhenClose)
end

function InvestMainDialog:OnFocus(focus)
    KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, focus)
    if focus then
        ---@type ServerDifferenceMgr
        local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
        ServerDifferenceMgr:RefreshNavigatorGoods(true)
    end
end

