function InvestMainDialog:RefreshShow(isPlay)
    GameUtils.Request(Interfaces.OverSeaFirstPay,{}, function(request,response)
        if checkInt(response.errCode) == 0 then
            self.data = response.data.firstGift
            if self.data.prices then
                local t = {}
                for goodsId, v in pairs(self.data.prices) do
                    t.currency = goodsId
                    t.original = checkNumber(v.original)
                    t.current = checkNumber(v.current)
                end
                self.data.prices = t
            end
            if playerComponent then
                local playerDojo = playerComponent.playerDojo
                if playerDojo then
                    if isSet(self.data,"signDayNumber") and isSet(self.data,"receiveId") then
                        local time
                        if isSet(self.data,"nextReceiveTime") then
                            time = self.data.nextReceiveTime + os.time()
                        end
                        playerDojo.overseaFirstGift = { signDayNumber = self.data.signDayNumber, receiveId = self.data.receiveId,nextReceiveTime = not isNull(time) and time or nil }
                    end
                    local isFirstPay = self:IsHavePay(playerDojo)
                    self:SetButtonState(isFirstPay)
                    local payInfo = self.data
                    if self:IsGoodExchange() then
                        local path = GoodsConfMgr:GetInstance():GetPhotoPathById(self.data.currency)
                        CfUtils.FillImage(self.currentImgIcon ,path)
                        local current = self.data.prices.current
                        local original = checkInt(self.data.prices.original)
                        CfUtils.FillText(self.Price,current)
                        if original == 0 then
                            KTool.SetActive(self.originImgIcon, false)    
                        else 
                            KTool.SetActive(self.originImgIcon, true)    
                        end 
                        KTool.SetActive(self.currentImgIcon, true)
                    else 
                        local windowsPriceId = CfUtils.GetWindowsPriceId(payInfo)
                        CfUtils.FillText(self.Price, localize( "<size=30>_YUAN_</size>_num_",{_num_ = CfUtils.GetPrice(windowsPriceId,payInfo.channelProductId) , _YUAN_ = CfUtils.GetCurrerySymbol() }))
                    end
                    self:SetStaticInfo()
                    for i = 1, RewardCount do
                        local rewardData = self:GetRewardByIndex(i)
                        self.rewardEnv[i]:RefreshShow(isFirstPay,playerDojo,rewardData,isPlay)
                    end
                    xRecord.af_internal("fpaygift", { playerId = tostring(playerComponent.playerDojo.playerId)})
                end    
            end
        end
    end )
end

---IsGoodExchange
---是否是道具兑换的逻辑
function InvestMainDialog:IsGoodExchange()
    local prices = self.data.prices  or {}
    return table.count(prices) > 0
end

function InvestMainDialog:GetRewardByIndex(i)
    local data = {}
    local goodIds = self.vo["reward"..i]
    local goodsNum = self.vo["rewardNum"..i]
    for i = 1, #goodIds do
        if goodIds[i] and goodsNum[i] then
            table.insert(data,{goodsId =goodIds[i],goodsNum = goodsNum[i],isSpecialReward = self:IsSpecialReward(goodIds[i])})
        end
    end
    return data
end

function InvestMainDialog:IsSpecialReward(id)
    for i, v in pairs(self.vo.specialRewardId) do
        if v == id then
            return true
        end
    end
    return false
end

function InvestMainDialog:IsHavePay(playerDojo)
    if not isNull(playerDojo.overseaFirstGift) and isSet(playerDojo.overseaFirstGift,"signDayNumber") then
        return true
    end
    return false
end

