function InvestMainDialog:SetRoleInfo()
    local roleData = CardConfMgr:GetInstance():GetCardByRefId(self.vo.roleId)
    print("->ContinuousRechargeDialog:SetRoleInfo", self.vo.roleId, table.dump(checkTable(roleData)))
    if isNull(roleData) then return end
