function InvestMainDialog:SetButtonState(state)
    KTool.SetActive(self.BtnHaveBuy.gameObject,state)
    KTool.SetActive(self.BtnBuy.gameObject,not state)
end

function InvestMainDialog:OnBuy()
    if self:IsGoodExchange() then
        ---@type ServerDifferenceMgr
        local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
        local current = self.data.prices.current
        ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
            currency = self.data.currency,
            current =  current,
        }, function(isSuccess)
            isSuccess = checkBool(isSuccess)
            if not isSuccess then
                return
            end
            ----请求兑换的逻辑
            GameUtils.Request(Interfaces.OverseaMallFirstGiftBuy,{
                productId  = self.data.productId,
                num = 1 ,
                currency = self.data.currency
            }, function(request,response)
                if checkInt(response.errCode) == 0 then
                    local oneReawards = response.data.rewards  or {}
                    local rewards = clone(oneReawards)
                    rewards[#rewards+1] = {
                        goodsId = self.data.currency ,
                        num = -current
                    }
                    local rewards2 = clone(response.data.rewards)
                    GoodsUtils.DrawRewards(rewards)
                    if #oneReawards > 0 then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards2, cb = function()
                            self._showTimeLimitedMainDialogWhenClose = true
                            self:RefreshShow(true)
                        end  } })
                    else 
                        self._showTimeLimitedMainDialogWhenClose = true
                        self:RefreshShow(true)
                    end
                   
                end
            end )
        end)
    else    
        local payInfo = self.data
        if payInfo then
            SDKService:GetInstance():PayMoney({
                productId = payInfo.productId,
                channelProductId = payInfo.channelProductId,
                productDesc = localize("首充"),
                payAmount = payInfo.price,
                data = payInfo
            })
        end
    end
end

--支付成功
function InvestMainDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        self._showTimeLimitedMainDialogWhenClose = true
        self:RefreshShow(true)
    end
end

function InvestMainDialog:__delete()
    self.data = nil
    self.rewardEnv = nil
    self._showTimeLimitedMainDialogWhenClose = nil
    if self.__EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil
    end
    self.controller = nil
end
return InvestMainDialog